-- Territórios geográficos (nível 1/2/3 por cidade, bordas em rios, serras e mudanças de bioma) no lugar dos anéis redondos,
-- cidades muradas de 140×120 tiles, sub-regiões, criaturas e áreas de caça por cidade e nível. Só acrescenta/atualiza dados de mapa.
-- Áreas de caça antigas que saíram do mapa ficam aposentadas (city_id nulo), nunca apagadas.

create table if not exists territory_grid(row int primary key, cells text not null);
alter table territory_grid enable row level security;
drop policy if exists territory_read on territory_grid; create policy territory_read on territory_grid for select using (true);
alter table cities add column if not exists rx int; alter table cities add column if not exists ry int; alter table cities add column if not exists regions jsonb;

update cities set x = 52, y = 40, rx = 0, ry = 0, regions = '["Campos de Arken","Fronteira de Arken","Ermos de Arken"]'::jsonb, sort = 0 where id = 'arken';
