-- zona = célula do território (16×16 tiles); coração e interiores são o nível 1 de Arken
create or replace function zone_at(px int, py int) returns jsonb language plpgsql stable set search_path = public as $$
declare ch int; c cities; tier int;
begin
  if py >= 4816 or (px >= 0 and px < 300 and py >= 0 and py < 200) then return jsonb_build_object('city', 'arken', 'ring', 1, 'name', 'Vila de Arken'); end if;
  select ascii(substr(cells, floor((px + 4900) / 16.0)::int + 1, 1)) - 97 into ch from territory_grid where row = floor((py + 5200) / 16.0)::int;
  if ch is null or ch < 0 then
    select * into c from cities order by power(px - case when heart then 150 else x end, 2) + power(py - case when heart then 100 else y end, 2) limit 1;
    return jsonb_build_object('city', c.id, 'ring', 3, 'name', coalesce(c.regions ->> 2, c.name));
  end if;
  select * into c from cities order by sort offset ch / 3 limit 1; tier := ch % 3 + 1;
  return jsonb_build_object('city', c.id, 'ring', tier, 'name', coalesce(c.regions ->> (tier - 1), c.name));
end $$;
grant execute on function zone_at(int, int) to authenticated;

